WITH enriched AS (SELECT *, FIRST_VALUE(budget) IGNORE NULLS OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_budget, ROW_NUMBER() OVER (ORDER BY budget DESC, id) AS row_seq, SUM(budget) OVER (PARTITION BY location, dept_name) AS location_sum_budget FROM departments) SELECT id, location, budget, row_seq, location_sum_budget, CASE WHEN location RLIKE '^(London|New York)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS location_zone FROM enriched ORDER BY location_zone DESC;
